mapper.insert:
INSERT INTO user_document_checklist (
    member_id, service_id, document_id, is_checked, memo
) VALUES (
    #{memberId}, #{serviceId}, #{documentId}, #{isChecked}, #{memo}
)

mapper.update:
UPDATE user_document_checklist
SET is_checked = #{isChecked},
    checked_at = CASE WHEN #{isChecked} = TRUE THEN NOW() ELSE NULL END
WHERE member_id = #{memberId}
  AND service_id = #{serviceId}
  AND document_id = #{documentId}

UPDATE user_document_checklist
SET memo = #{memo}
WHERE member_id = #{memberId}
  AND service_id = #{serviceId}
  AND document_id = #{documentId}

mapper.select:
SELECT COUNT(*)
FROM user_document_checklist
WHERE member_id = #{memberId}
  AND service_id = #{serviceId}
  AND is_checked = TRUE

SELECT COUNT(*)
FROM user_document_checklist
WHERE member_id = #{memberId}
  AND service_id = #{serviceId}

SELECT DISTINCT service_id
FROM user_document_checklist
WHERE member_id = #{memberId}
